INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('0a36e25e-4aaa-431f-bcde-843fc01353a1'::uuid, 'card_description', 'On the Vía de la Plata, the Roman Bridge of Salamanca crosses the Tormes River, its stretch toward the city still mostly original Roman work. Its exact date of construction is unknown.', 'The first fifteen of this bridge''s twenty-six arches date from Roman times. Rebuilt a number of times, its right bank section retains the majority of the original construction.', 'teaser-card-s038:0a36e25e-4aaa-431f-bcde-843fc01353a1:card_description', 'teaser-card-s038 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'c9293713144ee4de2ff2cc77027a2f4eaf00fc8f4c949f4e1dffce6d7f971839|acae92cf09c404745b815f50b943898267f339599e5919e3c3a4187967a5ebb2|acae92cf09c404745b815f50b943898267f339599e5919e3c3a4187967a5ebb2', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "The first fifteen of this bridge''s twenty-six arches date from Roman times. Rebuilt a number of times, its right bank section retains the majority of the original construction."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "the site is a bridge [S1]; the bridge has twenty-six arches [S5]; the first fifteen arches date from Roman times [S5]; the bridge has been rebuilt a number of times [S3]; the section on the right bank retains the majority of the original construction [S3]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "The site is a bridge (the Roman bridge of Salamanca over the Tormes) whose oldest arches are Roman. [SUPPORTED: https://www.spain.info/en/places-of-interest/roman-bridge-salamanca/]; The first fifteen of the bridge''s arches date from Roman times. [SUPPORTED: https://aracne.usal.es/virtual_visit/spa/puente.htm]; The bridge has twenty-six arches. [SUPPORTED: https://www.spain.info/en/places-of-interest/roman-bridge-salamanca/]; The bridge has been rebuilt a number of times. [SUPPORTED: https://aracne.usal.es/virtual_visit/spa/puente.htm]; The bridge''s right bank section retains the majority of the original (Roman) construction. [SUPPORTED: https://www.scielo.org.ar/scielo.php?script=sci_arttext&pid=S0325-11952007000100001]"}]'::jsonb),
    ('0de3da9b-5aeb-45a2-8f72-31ac1ad74a13'::uuid, 'card_description', 'Rising to 371 metres in the Derbyshire Peak District, the gritstone upland of Beeley Moor is a prehistoric landscape whose monuments include cairns, burial mounds and guidestones.', 'Cairns, burial mounds and guidestones mark this small gritstone upland. It is a prehistoric landscape of many protected monuments, and its highest point is 371 metres above sea level.', 'teaser-card-s038:0de3da9b-5aeb-45a2-8f72-31ac1ad74a13:card_description', 'teaser-card-s038 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '198927fc20a2538538111b3032a26057f64fc0934288e9600168a0ee35b82037|9e9ccb9738b8e9819a1503982448257e2d3b8723f3811b34857a3eef1cfc6f8f|9e9ccb9738b8e9819a1503982448257e2d3b8723f3811b34857a3eef1cfc6f8f', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Cairns, burial mounds and guidestones mark this small gritstone upland. It is a prehistoric landscape of many protected monuments, and its highest point is 371 metres above sea level."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "it is a small gritstone upland [S1]; cairns are among its monuments [S3]; burial mounds are among its monuments [S3]; guidestones are among its monuments [S3]; it is a prehistoric landscape [S3]; it has many protected monuments [S3]; its highest point is 371 metres above sea level [S2]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "The site (Beeley Moor, Derbyshire) is a small gritstone upland. [SUPPORTED: https://her.derbyshire.gov.uk/Designation/DDR902]; Cairns mark the moor. [SUPPORTED: https://her.derbyshire.gov.uk/Designation/DDR902]; Burial mounds mark the moor. [SUPPORTED: https://en.wikipedia.org/wiki/Scheduled_monuments_in_Derbyshire_Dales]; Guidestones mark the moor. [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR8453]; It is a prehistoric landscape. [SUPPORTED: https://her.derbyshire.gov.uk/Designation/DDR902]; It has many protected monuments (the list of scheduled monuments in Derbyshire Dales has about twenty entries in Beeley parish, among them several on Beeley Moor; the guidestone is Grade II listed). [SUPPORTED: https://en.wikipedia.org/wiki/Scheduled_monuments_in_Derbyshire_Dales]; Its highest point is 371 metres above sea level. [SUPPORTED: https://www.mudandroutes.com/summit/beeley-moor/]"}]'::jsonb),
    ('18911cb2-dff1-4d14-9110-de55c40706c0'::uuid, 'card_description', 'Goldsborough keeps a square Roman signal mound, roughly 30 m across and 1.4 m high. Excavations in 1918 found two skeletons and a large dog inside, jaws at one man''s throat.', 'A large dog''s jaws lay at a man''s throat in the tower of this Roman signal station. Excavations in 1918 revealed a second man, apparently stabbed in the back, and violent destruction.', 'teaser-card-s038:18911cb2-dff1-4d14-9110-de55c40706c0:card_description', 'teaser-card-s038 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '065a65df91c89b35547b36d9caff0a886771454c578f92e8792f953fadbd4193|9c6962d7e28d7e4eb753a64e4afde1a6e726d9e02872de15923fb7c2e67205ac|9c6962d7e28d7e4eb753a64e4afde1a6e726d9e02872de15923fb7c2e67205ac', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "A large dog''s jaws lay at a man''s throat in the tower of this Roman signal station. Excavations in 1918 revealed a second man, apparently stabbed in the back, and violent destruction."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "it was a Roman signal station [S1]; a large dog was found in the tower [S3]; the dog''s jaws were at a man''s throat [S3]; excavations took place in 1918 [S3]; a second man was found [S3]; the second man was apparently stabbed in the back [S3]; the excavations revealed evidence of violent destruction [S3]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "In the tower of this Roman signal station (Goldsborough, near Whitby), a large dog lay with its jaws (head) at a man''s throat. [SUPPORTED: https://www.maltonmuseum.co.uk/2021/05/29/the-fortlets-signal-stations-along-the-yorkshire-coast/]; The site is a Roman signal station. [SUPPORTED: https://www.archaeologicalresearchservices.com/wp-content/uploads/2018/01/Chapter-6-Whitby-West-Pier-to-Blackhall-Rocks.pdf]; The dog and the man were found in the station''s tower. [SUPPORTED: https://www.maltonmuseum.co.uk/2021/05/29/the-fortlets-signal-stations-along-the-yorkshire-coast/]; The site was excavated in 1918. [SUPPORTED: https://www.roman-britain.co.uk/places/goldsborough-signal-station/]; The excavations revealed a second man in the tower. [SUPPORTED: https://www.archaeologicalresearchservices.com/wp-content/uploads/2018/01/Chapter-6-Whitby-West-Pier-to-Blackhall-Rocks.pdf]; The second man had apparently been stabbed in the back. [SUPPORTED: https://www.maltonmuseum.co.uk/2021/05/29/the-fortlets-signal-stations-along-the-yorkshire-coast/]; The excavations revealed violent destruction (a violent end to the station). [SUPPORTED: https://www.archaeologicalresearchservices.com/wp-content/uploads/2018/01/Chapter-6-Whitby-West-Pier-to-Blackhall-Rocks.pdf]"}]'::jsonb),
    ('28163f7d-d85a-4fa6-ba08-c33cd62b1da8'::uuid, 'card_description', 'An Inca complex along the trail to Machu Picchu, serving as a rest stop and ceremonial waystation. Its buildings are oriented to align with Machu Picchu''s sun temple across the valley.', 'A corridor with 6-foot walls points to the sunrise during the June solstice. Over 80 structures make up this Inca complex, which an expedition concluded was a rest stop and roadside shrine.', 'teaser-card-s038:28163f7d-d85a-4fa6-ba08-c33cd62b1da8:card_description', 'teaser-card-s038 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'a56f41784d6170027164f50dbea1c422646a119a66e5fabaf250dbc751e14e52|b82212f0cc22cbe03e30606bc6da1e240ffb40c194bc5f2ebcdd18092a7252f3|b82212f0cc22cbe03e30606bc6da1e240ffb40c194bc5f2ebcdd18092a7252f3', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "A corridor with 6-foot walls points to the sunrise during the June solstice. Over 80 structures make up this Inca complex, which an expedition concluded was a rest stop and roadside shrine."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "the site has a corridor with 6-foot walls [S2]; the corridor points to the sunrise during the June solstice [S2]; the site has over 80 structures [S2]; it is an Inca complex [S1]; an expedition concluded it was a rest stop [S3]; an expedition concluded it was a roadside shrine [S3]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "A corridor at Llaqtapata points to the sunrise during the June solstice. [SUPPORTED: http://www.thomson.clara.net/llactapa.html]; The corridor has 6-foot (six feet high) walls. [SUPPORTED: http://www.thomson.clara.net/llactapa.html]; Over 80 structures make up the complex. [SUPPORTED: http://www.thomson.clara.net/llactapa.html]; Llaqtapata is an Inca complex. [SUPPORTED: http://www.thomson.clara.net/llactapa.html]; An expedition concluded the site was a rest stop. [SUPPORTED: http://www.thomson.clara.net/llactapa.html]; An expedition concluded the site was a roadside shrine. [SUPPORTED: http://www.thomson.clara.net/llactapa.html]"}]'::jsonb),
    ('2f68e3c4-6af8-40f0-833e-00602e7fe639'::uuid, 'card_description', 'Partly carved out of the mountain and ringed by cliffs, Geghard Monastery keeps churches dug into the rock, engraved khachkars and a cave spring sacred in pre-Christian times.', 'Some churches are dug entirely out of cliff rock, others are little more than caves. It is partly carved from a mountain, with engraved and freestanding khachkars.', 'teaser-card-s038:2f68e3c4-6af8-40f0-833e-00602e7fe639:card_description', 'teaser-card-s038 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', 'f4fea7d470b1ab844ecd802e17fe66747650f41cf865353129b0e0357edaa2a6|ce65f6ce1a89a1d3b158afb6f8073dc068d3f8b248391299783962dcec8c6afc|ce65f6ce1a89a1d3b158afb6f8073dc068d3f8b248391299783962dcec8c6afc', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Some churches are dug entirely out of cliff rock, others are little more than caves. It is partly carved from a mountain, with engraved and freestanding khachkars."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "some of its churches are dug entirely out of cliff rock [S2]; other churches are little more than caves [S2]; it is partly carved out of a mountain [S1]; it has engraved khachkars [S3]; it has free-standing khachkars [S3]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Some churches of this monastery (Geghard, Armenia) are dug entirely out of the cliff rock. [SUPPORTED: https://armeniahiddengems.aua.am/monument/geghard-monastery/]; Other churches/spaces of the complex are little more than caves. [SUPPORTED: https://unesco.ru/en/news/55-geghard/]; The monastery is partly carved from a mountain (part rock-hewn, part built above ground). [SUPPORTED: https://armeniahiddengems.aua.am/monument/geghard-monastery/]; The monastery has engraved khachkars (carved on the rocks). [SUPPORTED: https://unesco.ru/en/news/55-geghard/]; The monastery has freestanding khachkars. [SUPPORTED: https://armeniahiddengems.aua.am/monument/geghard-monastery/]"}]'::jsonb),
    ('2fb54462-31f6-441e-9b6c-64c6da84877b'::uuid, 'card_description', 'A karst cave system where the Tanagro river flows underground. Pile dwellings from the Bronze Age were discovered inside, showing people once lived in the caves.', 'Only these caves in Europe preserve the remains of a pile-dwelling village. Built over an underground river in the 2nd millennium BC, it sits in a karst cave system.', 'teaser-card-s038:2fb54462-31f6-441e-9b6c-64c6da84877b:card_description', 'teaser-card-s038 (teaser-card): teaser card, 165 characters, checked PASS, web-verified VERIFIED', 'b8f109fe54242f6f7a00894bc857ccd42561fa4bd6aa39250b4cae6ef37510e4|6e0f2ef82867427e9c700e07671f7828a96af39890b9e1931c8171548b0da81c|6e0f2ef82867427e9c700e07671f7828a96af39890b9e1931c8171548b0da81c', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Only these caves in Europe preserve the remains of a pile-dwelling village. Built over an underground river in the 2nd millennium BC, it sits in a karst cave system."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "they are the only caves in Europe that preserve the remains of a pile-dwelling village [S2]; the village was built over an underground river [S2]; the village dates to the 2nd millennium BC [S2]; it is a karst cave system [S1]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "These caves (the Pertosa Caves) are the only caves in Europe that preserve the remains of a pile-dwelling village. [SUPPORTED: https://archaeologymag.com/2025/10/hellenistic-sanctuary-in-pertosa-auletta-caves/]; The pile-dwelling village was built over an underground river. [SUPPORTED: https://pmc.ncbi.nlm.nih.gov/articles/PMC10570292/]; The pile-dwelling village was built in the 2nd millennium BC. [SUPPORTED: https://archaeologymag.com/2025/10/hellenistic-sanctuary-in-pertosa-auletta-caves/]; The village sits in a karst cave system. [SUPPORTED: https://pmc.ncbi.nlm.nih.gov/articles/PMC10570292/]"}]'::jsonb),
    ('33d2d754-e50a-4305-beff-87d2ad2c0227'::uuid, 'card_description', 'A 5th-century BC island city whose gold mines funded marble temples and a powerful navy. Thucydides, the father of political history, was exiled here.', 'Temples to Heracles and Athena survive among the ruins of a prosperous colony. Gold, marble and wine made the colony rich, and its agora keeps the cenotaph of the settler Glaucus.', 'teaser-card-s038:33d2d754-e50a-4305-beff-87d2ad2c0227:card_description', 'teaser-card-s038 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'b7cbf4bfd4a85f0c20cc1591c51dc83820ed0cb12b0915f659444eab39765061|0682c7dd1ce28195abbc4466d485cf1d69174a9cbb2974de764f2553420a455a|0682c7dd1ce28195abbc4466d485cf1d69174a9cbb2974de764f2553420a455a', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Temples to Heracles and Athena survive among the ruins of a prosperous colony. Gold, marble and wine made the colony rich, and its agora keeps the cenotaph of the settler Glaucus."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "temples to Heracles and Athena survive among the ruins [S4]; it was a colony [S1]; the colony was prosperous [S1]; gold made the colony rich [S2]; marble made the colony rich [S2]; wine made the colony rich [S2]; its agora preserves the cenotaph of the settler Glaucus [S3]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "The agora of the colony (ancient Thasos) keeps a monument of Glaucus. [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.04.0006%3Aentry%3Dthasos]; The monument of Glaucus in the agora is a cenotaph. [SUPPORTED: https://de.wikipedia.org/wiki/Monument_des_Glaukos]; Glaucus was a settler of the colony. [SUPPORTED: https://golden-greece.gr/en/archaeological/egeo/thasos/arxaia-agora]; A temple to Heracles survives among the ruins. [SUPPORTED: https://de.wikipedia.org/wiki/Thasos_(Antike)]; A temple to Athena survives among the ruins. [SUPPORTED: https://de.wikipedia.org/wiki/Thasos_(Antike)]; The settlement was a colony. [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.04.0006%3Aentry%3Dthasos]; The colony was prosperous. [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.04.0006%3Aentry%3Dthasos]; Gold made the colony rich. [SUPPORTED: https://de.wikipedia.org/wiki/Thasos_(Antike)]; Marble made the colony rich. [SUPPORTED: https://www.perseus.tufts.edu/hopper/text?doc=Perseus%3Atext%3A1999.04.0006%3Aentry%3Dthasos]; Wine made the colony rich. [SUPPORTED: https://de.wikipedia.org/wiki/Thasos_(Antike)]"}]'::jsonb),
    ('37d54e47-00e9-4647-82c8-3ee56814692d'::uuid, 'card_description', 'At San Jose de Moro, boot-shaped Moche tombs held ceramics and metals, and several burials revealed high status women whose attire and offerings still speak of their importance.', 'Several high status women were buried here, and their attire marks their importance. Their offerings tell the same tale, and large spaces for making and storing chicha point to feasting.', 'teaser-card-s038:37d54e47-00e9-4647-82c8-3ee56814692d:card_description', 'teaser-card-s038 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'ee50ef71728a74b5a5bf7d105547ee97e836261a15c18e756b194b98f38dea41|48f07ee940b12722d9a128ce68d67af7ff75f0b64d14a77ef82af3b787389483|48f07ee940b12722d9a128ce68d67af7ff75f0b64d14a77ef82af3b787389483', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Several high status women were buried here, and their attire marks their importance. Their offerings tell the same tale, and large spaces for making and storing chicha point to feasting."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "several high status women were buried at the site [S7]; their attire indicates their importance [S8]; their burial offerings also indicate their importance [S8]; there are large spaces for producing and storing chicha [S6]; these spaces indicate feasting [S6]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Several high-status women were buried at San José de Moro. [SUPPORTED: http://sanjosedemoro.pucp.edu.pe/02english/05sacerdotiza.html]; The women''s attire marks their importance. [SUPPORTED: http://sanjosedemoro.pucp.edu.pe/02english/05sacerdotiza.html]; The women''s offerings also mark their importance. [SUPPORTED: http://sanjosedemoro.pucp.edu.pe/02english/05sacerdotiza.html]; The site has large spaces for making and storing chicha. [SUPPORTED: http://sanjosedemoro.pucp.edu.pe/02english/02mochicatardio.html]; The chicha production and storage point to feasting. [SUPPORTED: http://sanjosedemoro.pucp.edu.pe/02english/02mochicatardio.html]"}]'::jsonb),
    ('8424266d-c9ed-42b0-b04c-004e21cd06de'::uuid, 'card_description', 'At Weissenburg, near the Roman limes, the fort once called Biriciana keeps a reconstructed north gateway, large thermal baths and building remains lying partly underground.', 'A rebuilt north gateway stands at this Roman fort. Part of a UNESCO World Heritage Site, it also holds partly underground building remains and large thermal baths.', 'teaser-card-s038:8424266d-c9ed-42b0-b04c-004e21cd06de:card_description', 'teaser-card-s038 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', '24fef9f40c44e85bca59f3ae01aa2fcd2996da5de70c9c89e5954585ebfac822|20cb7c9b514d137f3f87d40de6cab3bd81b56d00a4db3ef1233a95f668bf3541|20cb7c9b514d137f3f87d40de6cab3bd81b56d00a4db3ef1233a95f668bf3541', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "A rebuilt north gateway stands at this Roman fort. Part of a UNESCO World Heritage Site, it also holds partly underground building remains and large thermal baths."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "a rebuilt north gateway stands at the site [S4]; the site is a Roman fort [S1]; it is (part of) a UNESCO World Heritage Site [S1]; it holds partly underground building remains [S4]; it holds large thermal baths [S4]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "A rebuilt (reconstructed) north gateway stands at this site [SUPPORTED: https://www.deutsche-limeskommission.de/index.php?id=94]; The site is a Roman fort [SUPPORTED: https://www.deutsche-limeskommission.de/index.php?id=94]; It is part of a UNESCO World Heritage Site [SUPPORTED: https://de.wikipedia.org/wiki/Kastell_Wei%C3%9Fenburg]; It holds partly underground building remains [SUPPORTED: https://de.wikipedia.org/wiki/Kastell_Wei%C3%9Fenburg]; It holds large thermal baths [SUPPORTED: https://de.wikipedia.org/wiki/R%C3%B6mische_Thermen_(Wei%C3%9Fenburg)]"}]'::jsonb),
    ('9ae31b41-d78d-44da-824d-43487ec611f0'::uuid, 'card_description', 'On the northern edge of the South Downs, the ditches of Combe Hill held Ebbsfleet ware pottery and three polished stone axes, the axes laid down perhaps not long after their ditch was dug.', 'A large quantity of Ebbsfleet ware pottery lay in one ditch of this enclosure. It sits only 800 m from another Neolithic enclosure, and the two locations are visible from each other.', 'teaser-card-s038:9ae31b41-d78d-44da-824d-43487ec611f0:card_description', 'teaser-card-s038 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '04c012b1342f45887743508c7a3bc6c296ae7e58d853a13e4a0db694cc919370|8a500c9f9b45775feecb002485dafb40dd2a54493d242c96c425d61bd1be5c18|8a500c9f9b45775feecb002485dafb40dd2a54493d242c96c425d61bd1be5c18', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "A large quantity of Ebbsfleet ware pottery lay in one ditch of this enclosure. It sits only 800 m from another Neolithic enclosure, and the two locations are visible from each other."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "a large quantity of Ebbsfleet ware pottery was found in one of the site''s ditches [S5]; the site is an enclosure [S1]; the site is a Neolithic enclosure (implied by ''another Neolithic enclosure'') [S7]; it lies only 800 m from another Neolithic enclosure [S7]; the two locations are visible from each other [S7]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Ebbsfleet ware pottery was found in a ditch of the Combe Hill enclosure (its Neolithic pottery is dominated by Ebbsfleet ware). [SUPPORTED: http://www.sussexarch.org.uk/saaf/combehill.html]; The quantity of Ebbsfleet ware found was large. [SUPPORTED: http://www.sussexarch.org.uk/saaf/combehill.html]; The site is an enclosure (a Neolithic causewayed enclosure). [SUPPORTED: http://www.sussexarch.org.uk/saaf/combehill.html]; It sits only 800 m from another enclosure (Butts Brow). [SUPPORTED: https://heritageeastbourne.home.blog/2020/08/28/butts-brow-excavation-a-few-weeks-later/]; The other enclosure (Butts Brow) is Neolithic. [SUPPORTED: https://heritageeastbourne.home.blog/2020/08/28/butts-brow-excavation-a-few-weeks-later/]; The two locations are visible from each other. [SUPPORTED: https://heritageeastbourne.home.blog/2020/08/28/butts-brow-excavation-a-few-weeks-later/]"}]'::jsonb),
    ('ccfefb01-6020-4d87-8ae3-2fa94ba33837'::uuid, 'card_description', 'An ancient sanctuary where twin temples honored Apollo and Artemis side by side. A Hellenistic temple and Greek theatre share the same sacred grounds.', 'Galatians looted this ancient Greek sanctuary, a serious setback. That came in 277/76 BC, and the sanctuary was famed in antiquity for its oracle of Apollo in the god''s temple.', 'teaser-card-s038:ccfefb01-6020-4d87-8ae3-2fa94ba33837:card_description', 'teaser-card-s038 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'c5268b11cbc1b270079842f2fc1b4cedfd81a0acbc48e1d7b457ab7acbe78faf|db14be039760a5098c773a61757639621d19f1bd43a0b0997dc766e9b2def274|db14be039760a5098c773a61757639621d19f1bd43a0b0997dc766e9b2def274', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Galatians looted this ancient Greek sanctuary, a serious setback. That came in 277/76 BC, and the sanctuary was famed in antiquity for its oracle of Apollo in the god''s temple."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Galatians looted the site [S6]; it is an ancient Greek sanctuary [S1]; the looting was a serious setback [S6]; the looting came in 277/76 BC [S6]; the sanctuary was famed in antiquity for its oracle of Apollo [S2]; the oracle was situated within the god''s temple [S2]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Galatians looted this sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Galatia]; The site is an ancient Greek sanctuary [SUPPORTED: https://www.fhw.gr/choros/miletus/en/didima.php?submenu_top_id=0b]; The looting was a serious setback for the sanctuary [UNVERIFIABLE, no proving quote: None]; The looting came in 277/76 BC [SUPPORTED: https://www.philipharland.com/Blog/2023/01/celts-galatians-priene-inscription-on-galatian-impiety-and-savagery-during-the-invasion-ca-278-270-bce/]; The sanctuary was famed in antiquity for its oracle of Apollo [SUPPORTED: https://www.fhw.gr/choros/miletus/en/didima.php?submenu_top_id=0b]; The oracle was situated in the god''s temple [SUPPORTED: https://www.fhw.gr/choros/miletus/en/didima.php?submenu_top_id=0b]"}]'::jsonb),
    ('cfb36f32-10c1-477e-8a10-203dea937c00'::uuid, 'card_description', 'At about 4,433 metres in the Pasco Region, Kuntuyuq keeps its rock paintings on a mountain of the same name that rises up to 4,475 metres, north-west of the lake Allqaqucha.', 'About 4,433 metres up, rock paintings mark a site on a mountain. The mountain itself rises up to 4,475 metres above sea level and shares its name with the site.', 'teaser-card-s038:cfb36f32-10c1-477e-8a10-203dea937c00:card_description', 'teaser-card-s038 (teaser-card): teaser card, 160 characters, checked PASS, web-verified VERIFIED', '1569913501c4b16c6b1bd06cda07a38cc2a1d7dfb6a89d48b954087c934b54d0|97b5180385232a94d3d2a1ff30894e0efa340d1485474d660fc50626d0ac0348|97b5180385232a94d3d2a1ff30894e0efa340d1485474d660fc50626d0ac0348', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "About 4,433 metres up, rock paintings mark a site on a mountain. The mountain itself rises up to 4,475 metres above sea level and shares its name with the site."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "the site lies about 4,433 metres up [S4]; the site has rock paintings [S1]; the site is on a mountain [S1]; the mountain rises up to 4,475 metres above sea level [S3]; the mountain shares its name with the site [S1]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "The site is marked by rock paintings [SUPPORTED: http://consultasenlinea.mincetur.gob.pe/fichaInventario/index.aspx?cod_Ficha=6980]; The site lies on a mountain [SUPPORTED: http://consultasenlinea.mincetur.gob.pe/fichaInventario