    ('d36d9012-fba6-40fc-9f0d-ff865ef0f2a4'::uuid, 'card_description', 'A Roman lighthouse from the 1st century AD that still functions as a navigational beacon. At 55 meters tall, it is the oldest working lighthouse in the world.', 'Only one fully preserved Roman lighthouse still guides ships. Its tower stands 55 metres tall, 34 of them Roman masonry, and the outline of an old spiral ramp still shows.', 'teaser-card-s038:d36d9012-fba6-40fc-9f0d-ff865ef0f2a4:card_description', 'teaser-card-s038 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', '0e683efdd8e9205f88866f5e2b1ab058a6b3bd8c1d0cbc5f3a529d7796ef302d|9be5ed07cb296d39ad0c8aa611ce761fbbd48639054fcf644bd2ddf731492f75|9be5ed07cb296d39ad0c8aa611ce761fbbd48639054fcf644bd2ddf731492f75', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Only one fully preserved Roman lighthouse still guides ships. Its tower stands 55 metres tall, 34 of them Roman masonry, and the outline of an old spiral ramp still shows."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "it is a Roman lighthouse [S1]; it is the only fully preserved Roman lighthouse still used to guide ships (maritime signalling) [S2]; the tower stands 55 metres tall [S3]; 34 metres of the tower are Roman masonry [S3]; the original tower had a spiral ramp [S4]; the outline of that ramp is still visible [S5]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "It is the only (fully preserved) Roman lighthouse that still guides ships [SUPPORTED: https://ciav.torredeherculesacoruna.com/en/operation-of-the-lighthouse/]; It is a lighthouse built by the Romans [SUPPORTED: https://ciav.torredeherculesacoruna.com/en/operation-of-the-lighthouse/]; Its Roman structure is preserved [SUPPORTED: https://ciav.torredeherculesacoruna.com/en/construction-methods/]; It still guides ships today (an operating lighthouse) [SUPPORTED: https://ciav.torredeherculesacoruna.com/en/operation-of-the-lighthouse/]; The tower stands 55 metres tall [SUPPORTED: https://ciav.torredeherculesacoruna.com/en/construction-methods/]; 34 metres of the tower are Roman masonry [SUPPORTED: https://ciav.torredeherculesacoruna.com/en/construction-methods/]; The tower once had an old (Roman) spiral ramp rising to its top [SUPPORTED: https://ciav.torredeherculesacoruna.com/en/construction-methods/]; The outline of that spiral ramp still shows on the tower [SUPPORTED: https://ciav.torredeherculesacoruna.com/en/construction-methods/]"}]'::jsonb),
    ('e765ff49-b186-4cf0-b32a-94a3aa453de9'::uuid, 'card_description', 'Found on the banks of the River Witham in 2001, the Fiskerton Log Boat was worked from a single oak trunk that still bears axe marks, then deliberately sunk as an offering.', 'Sunk on purpose as an offering, this Iron Age craft may have been made for that. It was made from one oak trunk and still bears axe marks, and a board slotted into a groove closes its stern.', 'teaser-card-s038:e765ff49-b186-4cf0-b32a-94a3aa453de9:card_description', 'teaser-card-s038 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '121544fa7160573b47490384386628b29b701030df3dac807be205986b144cfb|90eacd4a37ffc621547a7f56e67e4047360860f66ca077cf1cc5838144cd968c|90eacd4a37ffc621547a7f56e67e4047360860f66ca077cf1cc5838144cd968c', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Sunk on purpose as an offering, this Iron Age craft may have been made for that. It was made from one oak trunk and still bears axe marks, and a board slotted into a groove closes its stern."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "the craft was deliberately sunk as an offering [S3]; it dates to the Iron Age [S1]; it is a boat (craft) [S1]; it may have been specially made for that purpose [S3]; it was made from a single oak tree trunk [S2, S4]; it still bears axe marks from its making [S2]; its stern is closed by a board slotted into a groove [S5]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "The boat was sunk on purpose as an offering [SUPPORTED: https://www.lincolnmuseum.com/visiting-us/exhibit/fiskerton-log-boat]; It is a craft (a boat) [SUPPORTED: https://artsandculture.google.com/asset/fiskerton-log-boat-the-collection-lincoln/xgGtZvvyyATZ4w?hl=en]; It is an Iron Age boat [SUPPORTED: https://artsandculture.google.com/asset/fiskerton-log-boat-the-collection-lincoln/xgGtZvvyyATZ4w?hl=en]; It may have been made specifically for that purpose (to be offered) [SUPPORTED: https://www.lincolnmuseum.com/visiting-us/exhibit/fiskerton-log-boat]; It was made from a single tree trunk [SUPPORTED: https://www.lincolnmuseum.com/visiting-us/exhibit/fiskerton-log-boat]; The trunk was oak [SUPPORTED: https://artsandculture.google.com/asset/fiskerton-log-boat-the-collection-lincoln/xgGtZvvyyATZ4w?hl=en]; It still bears axe marks [SUPPORTED: https://artsandculture.google.com/asset/fiskerton-log-boat-the-collection-lincoln/xgGtZvvyyATZ4w?hl=en]; Its stern is closed by a board slotted into a groove [SUPPORTED: https://artsandculture.google.com/asset/fiskerton-log-boat-the-collection-lincoln/xgGtZvvyyATZ4w?hl=en]"}]'::jsonb),
    ('f2046843-60ed-4081-8bbe-95cde34ec6a7'::uuid, 'card_description', 'On the Bou Regreg estuary in Rabat, the walls of Chellah enclose a religious complex Marinid sultans built beside their mausoleums, damaged over the centuries by earthquakes and looting.', 'Earthquakes and looting damaged this fortified necropolis over the centuries. By the mid-14th century, Marinid sultans walled off part of the site and built a religious complex inside it.', 'teaser-card-s038:f2046843-60ed-4081-8bbe-95cde34ec6a7:card_description', 'teaser-card-s038 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '2e56f25f4f4de6cd19d33a7570d8219d64c73e53711afb1d6263063ea7faf6f0|f3233e394456953894b72a4375fd6badf4ac6a282e78ecec629bbb5976c55d77|f3233e394456953894b72a4375fd6badf4ac6a282e78ecec629bbb5976c55d77', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Earthquakes and looting damaged this fortified necropolis over the centuries. By the mid-14th century, Marinid sultans walled off part of the site and built a religious complex inside it."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check2-002 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "the site is a fortified necropolis [S1]; earthquakes damaged it over the centuries [S4]; looting damaged it over the centuries [S4]; by the mid-14th century Marinid sultans had enclosed part of the site with walls [S3]; they built a religious complex inside the enclosure [S3]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "The site is a fortified necropolis [SUPPORTED: https://islamicart.museumwnf.org/database_item.php?id=monument;ISL;ma;Mon01;5;en]; Earthquakes damaged the necropolis [SUPPORTED: https://islamicart.museumwnf.org/database_item.php?id=monument;ISL;ma;Mon01;5;en]; Looting damaged the necropolis [SUPPORTED: https://www.rabat-maroc.net/chellah/]; The damage happened over the centuries [SUPPORTED: https://www.rabat-maroc.net/chellah/]; It was a necropolis of the Marinid sultans [SUPPORTED: https://islamicart.museumwnf.org/database_item.php?id=monument;ISL;ma;Mon01;5;en]; By the mid-14th century Marinid sultans had walled the site [SUPPORTED: https://islamicart.museumwnf.org/database_item.php?id=monument;ISL;ma;Mon01;5;en]; The walls enclosed only part of the (older) site [SUPPORTED: https://fr.wikipedia.org/wiki/Chellah]; The Marinids built a religious complex inside the walls [SUPPORTED: https://islamicart.museumwnf.org/database_item.php?id=monument;ISL;ma;Mon01;5;en]"}]'::jsonb),
    ('fa2037ed-54b7-425a-9650-27f0e25ac274'::uuid, 'card_description', 'The Beckhampton Avenue curved from Avebury towards The Longstones, yet only one stone, called Adam, still stands. Excavations in 2000 revealed the parallel rows of holes that held them.', 'Parallel rows of holes show where the stones of this prehistoric line once stood. Excavation uncovered 120 metres of a double row, with the stones placed at 15 metres intervals.', 'teaser-card-s038:fa2037ed-54b7-425a-9650-27f0e25ac274:card_description', 'teaser-card-s038 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '012a9a9c8b6ae004c21ca179b73ee1f7e885a0843fda4c4d37e9e9678bcfcf56|9cf84b4c8d3c4473f1400c75fa3dfb159ea180d33c37bac2534b7a6269156271|9cf84b4c8d3c4473f1400c75fa3dfb159ea180d33c37bac2534b7a6269156271', '[{"source": "lane WB run wb-shorts-pilot-2026-10-18: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Parallel rows of holes show where the stones of this prehistoric line once stood. Excavation uncovered 120 metres of a double row, with the stones placed at 15 metres intervals."}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "parallel rows of holes were found [S5]; the holes held the stones of the monument [S5]; the monument is a prehistoric line (avenue) of stones [S1]; excavation uncovered 120 metres of it [S6]; it was a double row of stones [S6]; the stones were placed at 15-metre intervals [S6]"}, {"source": "lane WB run wb-shorts-pilot-2026-10-18: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-pilot-2026-10-18/OUTCOMES.jsonl", "quote": "Parallel rows of holes show where the stones of the Beckhampton Avenue once stood. [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]; The stones of the avenue no longer stand where they once stood (they are gone). [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]; The Beckhampton Avenue is a prehistoric line (avenue) of stones. [SUPPORTED: https://researchframeworks.org/stonehengeavebury/avebury-resource-assessment-part-two-period-based-assessments/]; Excavation uncovered 120 metres of the avenue. [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]; The uncovered stretch was a double row of stones. [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]; The stones were placed at 15-metre intervals. [SUPPORTED: https://www.bristol.ac.uk/news/2007/11920111227.html]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 16;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s038', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s038'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s038'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 16 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s038'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s038' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
